-- Schema changes: add CV columns and remove auth FK
ALTER TABLE profiles DROP CONSTRAINT IF EXISTS profiles_id_fkey;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS email text UNIQUE;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS bio text;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS education text;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS languages text;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS years_of_experience integer;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS certifications text[] DEFAULT '{}';
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS experience jsonb DEFAULT '[]';

-- Bulk insert all consultants
ON CONFLICT (email) DO NOTHING;

-- Update sign-up policy to also allow update (for linking auth accounts)
DROP POLICY IF EXISTS "consultant creates own profile" ON profiles;
CREATE POLICY "consultant creates own profile" ON profiles FOR INSERT WITH CHECK (auth.uid() = id OR email = (SELECT email FROM auth.users WHERE id = auth.uid()));
CREATE POLICY "consultant links own profile" ON profiles FOR UPDATE USING (email = (SELECT email FROM auth.users WHERE id = auth.uid()));

